export const BETUL_SEED_WARD_ID_PREFIX = 'betul-seed-ward-';

export function isSyntheticSeedWardId(id?: string | null): boolean {
  return Boolean(id && id.startsWith(BETUL_SEED_WARD_ID_PREFIX));
}

export function makeSyntheticSeedWardId(wardNumber: number): string {
  return `${BETUL_SEED_WARD_ID_PREFIX}${String(wardNumber).padStart(2, '0')}`;
}

export function seedToWard(seed: BetulWardSeed): Ward {
  return {
    id: makeSyntheticSeedWardId(seed.ward_number),
    ward_number: seed.ward_number,
    name: seed.name,
    name_hindi: seed.name_hindi,
    description: seed.description,
    center_latitude: seed.center_latitude,
    center_longitude: seed.center_longitude,
    radius_meters: seed.radius_meters,
    pincode: seed.pincode,
    is_active: seed.is_active,
    boundary_coordinates: seed.boundary_coordinates,
    area_sq_meters: seed.area_sq_meters,
    assigned_department_id: null,
    assigned_head_id: null,
    assigned_supervisor_id: null,
    created_at: BETUL_MUNICIPALITY_META.generatedAt,
    updated_at: BETUL_MUNICIPALITY_META.generatedAt,
    created_by: null,
  };
}

/**
 * Enriches Supabase `wards` rows with official Betul Municipality polygons,
 * geodesic areas, and centers when missing in the database.
 * When `dbWards` is empty (before DB seeding or when anon RLS blocks reads),
 * falls back cleanly to the official 33-ward Betul dataset for interactive previews.
 */
export function mergeWithOfficialBetulWards(
  dbWards: Ward[],
  includeMissingSeedWards = false,
): Ward[] {
  const activeDbWards = (dbWards || []).filter((w) => w.is_active !== false);
  if (activeDbWards.length === 0) {
    return BETUL_WARDS_SEED.map(seedToWard).sort(
      (a, b) => a.ward_number - b.ward_number,
    );
  }

  // Deduplicate active DB rows by ward_number (prefer row that already has a polygon)
  const dedupedByNumber = new Map<number, Ward>();
  for (const w of activeDbWards) {
    const prev = dedupedByNumber.get(w.ward_number);
    if (!prev) {
      dedupedByNumber.set(w.ward_number, w);
    } else if (
      getWardPolygons(prev.boundary_coordinates).length === 0 &&
      getWardPolygons(w.boundary_coordinates).length > 0
    ) {
      dedupedByNumber.set(w.ward_number, w);
    }
  }

  const seedByNumber = new Map<number, BetulWardSeed>(
    BETUL_WARDS_SEED.map((s) => [s.ward_number, s]),
  );

  const enriched = Array.from(dedupedByNumber.values()).map((w) => {
    const seed = seedByNumber.get(w.ward_number);
    if (!seed) return w;

    const hasDbPoly = getWardPolygons(w.boundary_coordinates).length > 0;
    const upgradingFromLegacyRadius = !hasDbPoly && seed.boundary_coordinates !== null;

    return {
      ...w,
      name: w.name?.trim() || seed.name,
      name_hindi: w.name_hindi || seed.name_hindi,
      description: upgradingFromLegacyRadius
        ? seed.description
        : w.description || seed.description,
      pincode: w.pincode || seed.pincode,
      center_latitude: upgradingFromLegacyRadius
        ? seed.center_latitude
        : w.center_latitude ?? seed.center_latitude,
      center_longitude: upgradingFromLegacyRadius
        ? seed.center_longitude
        : w.center_longitude ?? seed.center_longitude,
      radius_meters: upgradingFromLegacyRadius
        ? seed.radius_meters
        : w.radius_meters || seed.radius_meters,
      area_sq_meters:
        w.area_sq_meters && w.area_sq_meters > 0 && hasDbPoly
          ? w.area_sq_meters
          : seed.area_sq_meters,
      boundary_coordinates: hasDbPoly
        ? w.boundary_coordinates
        : seed.boundary_coordinates,
    };
  });

  if (includeMissingSeedWards) {
    const presentNumbers = new Set(enriched.map((w) => w.ward_number));
    for (const seed of BETUL_WARDS_SEED) {
      if (!presentNumbers.has(seed.ward_number)) {
        enriched.push(seedToWard(seed));
      }
    }
  }

  return enriched.sort((a, b) => a.ward_number - b.ward_number);
}
